//! About-pane state plumbing: peer-version probing, the COMPONENTS
//! row catalogue, and the diagnostic-blob assembler.
//!
//! The third-party-notices fallback path (FHS lookup → embedded
//! blob → tempfile + `xdg-open`) lives here too because it shares
//! the build-time `NOTICES_HTML` const generated by `cargo-about`.

use std::sync::Arc;

use gettextrs::gettext;
use slint::{Model, SharedString};

use crate::{AboutComponentRow, AppWindow, ServiceHealth, diagnostic};

/// Compile-time version of this binary. Surfaces in the About pane's
/// header chip and is the release each service's health is judged
/// against.
pub(crate) const GUI_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Project repository URL — picked up from the workspace package
/// metadata at compile time. The About pane's `View source` button
/// opens this; `Report issue` appends `/issues` (the list view, not
/// `/new`, so users encounter existing reports before filing a
/// duplicate).
pub(crate) const REPO_URL: &str = env!("CARGO_PKG_REPOSITORY");

/// Build-time-embedded copy of the workspace-wide third-party FOSS
/// attribution, generated by `build.rs` via `cargo-about`. Used by
/// `open_notices_html` as a source-build fallback when no installed
/// copy is found.
const NOTICES_HTML: &str = include_str!(concat!(env!("OUT_DIR"), "/THIRD-PARTY-LICENSES.html"));

/// Conventional FHS install path for the bundled attribution. Read
/// directly when present so the user opens the same file system
/// audit tools (rpm-sequoia, lintian, etc.) inspect on installations
/// that follow the FHS doc-path convention.
const NOTICES_HTML_FHS: &str = "/usr/share/doc/tisvlay/THIRD-PARTY-LICENSES.html";

/// Locate an installed copy of the third-party-licenses HTML, if any.
/// Tries the FHS path first, then walks up from `current_exe()` to
/// derive a `$prefix` and look in `$prefix/share/doc/tisvlay/`. The
/// `current_exe()` path covers any installer that places the binary
/// at `<prefix>/bin/<name>` and the doc at `<prefix>/share/doc/...`
/// — Nix store paths, AppImage mounts, and `make install` to
/// non-FHS prefixes (`/usr/local/`, `/opt/...`). Falls through to
/// the embedded-blob → tempfile path in `open_notices_html` when no
/// installed copy is found.
fn installed_notices_path() -> Option<std::path::PathBuf> {
    let fhs = std::path::PathBuf::from(NOTICES_HTML_FHS);
    if fhs.exists() {
        return Some(fhs);
    }
    let exe = std::env::current_exe().ok()?;
    let prefix = exe.parent()?.parent()?;
    let rel = prefix.join("share/doc/tisvlay/THIRD-PARTY-LICENSES.html");
    rel.exists().then_some(rel)
}

/// Hand off the workspace-wide attribution HTML to the user's
/// browser. Prefers an installed copy when present; otherwise
/// writes the build-time-embedded blob to a per-process temp file
/// and points the browser at that. Both paths route through
/// `webbrowser::open` (xdg-open under the hood on Linux) so the
/// user's default browser handles it.
pub(crate) fn open_notices_html() -> anyhow::Result<()> {
    if let Some(installed) = installed_notices_path() {
        webbrowser::open(&installed.to_string_lossy())?;
        return Ok(());
    }

    // Dev / source-build fallback: write the embedded HTML to a
    // securely-created temp file. `tempfile::Builder::tempfile`
    // uses `O_CREAT|O_EXCL` with a random suffix — defends against
    // the symlink/hardlink TOCTOU race a predictable
    // `/tmp/<name>-<pid>.html` path would expose. Persisted with
    // `keep()` so the OS doesn't delete the file before the browser
    // gets a chance to read it (the browser opens asynchronously
    // and returns immediately); /tmp's standard cleanup policies
    // handle eventual eviction.
    let mut tf = tempfile::Builder::new()
        .prefix("tisvlay-third-party-licenses-")
        .suffix(".html")
        .tempfile()?;
    use std::io::Write;
    tf.write_all(NOTICES_HTML.as_bytes())?;
    let (_, path) = tf.keep()?;
    webbrowser::open(&path.to_string_lossy())?;
    Ok(())
}

/// Static catalogue of every binary that ships in the package.
/// `name` is the binary identifier (kept for diagnostic-blob lookup);
/// `friendly` is the human-readable label shown as the row title;
/// `description` is the rich one-line sentence describing what the
/// component does. The monospace parens text (each peer's wire
/// identity: its liveliness key, or the GUI's real D-Bus activation
/// name) is computed per row in [`make_about_components`] — it
/// carries the runtime site, so it can't live in this const.
const COMPONENT_CATALOGUE: &[(&str, &str, &str)] = &[
    (
        "tisvlay-daemon",
        "Daemon",
        "Device management, WoL at boot, system profiles.",
    ),
    (
        "tisvlay-session",
        "Session",
        "User-profile assignments and session-event dispatch.",
    ),
    (
        "tisvlay-tray",
        "Tray",
        "Tray icon, menu actions, real-time TV state.",
    ),
    (
        "tisvlay-gui",
        "GUI",
        "Graphical interface for TisVlay management.",
    ),
    (
        "tisvlay",
        "CLI",
        "Command-line interface for TisVlay management.",
    ),
];

/// A peer process's release and config path, from its client's release
/// check (`service_info`). `config_path` is empty when the peer has no
/// config file (GUI).
#[derive(Clone, Default, Debug)]
pub(crate) struct PeerInfo {
    pub version: String,
    pub config_path: String,
}

impl From<tisvlay::ServiceInfo> for PeerInfo {
    fn from(info: tisvlay::ServiceInfo) -> Self {
        Self {
            version: info.version,
            config_path: info.state_path,
        }
    }
}

/// A present peer's health, from its release against this GUI's: the
/// same release, a compatible one (only the patch differs), or one the
/// two can't talk across. Compatibility is `tisvlay_protocol::compatible`,
/// the rule the SDK's handshake applies, so a red chip always matches
/// the version banner.
fn release_health(theirs: &str) -> ServiceHealth {
    if theirs == GUI_VERSION {
        ServiceHealth::Ok
    } else if tisvlay_protocol::compatible(GUI_VERSION, theirs) {
        ServiceHealth::Skew
    } else {
        ServiceHealth::Incompatible
    }
}

/// A service's health, rendered by the sidebar dot and its About row:
/// offline unless its liveliness token is up, then decided by its
/// release. A live service whose release isn't read yet counts as ok,
/// since nothing says otherwise.
pub(crate) fn service_health(online: bool, info: Option<&PeerInfo>) -> ServiceHealth {
    match (online, info) {
        (false, _) => ServiceHealth::Offline,
        (true, Some(info)) => release_health(&info.version),
        (true, None) => ServiceHealth::Ok,
    }
}

/// The hover tip for a service row's version chip.
fn service_tip(health: ServiceHealth, theirs: Option<&str>) -> String {
    match (health, theirs) {
        (ServiceHealth::Offline, _) => gettext("Not running"),
        (ServiceHealth::Ok, Some(_)) => gettext("Same release as this GUI"),
        (ServiceHealth::Ok, None) => gettext("Release not read yet"),
        (ServiceHealth::Skew, theirs) => {
            gettext("Runs {0}, this GUI {1}: compatible, only the patch release differs")
                .replace("{0}", theirs.unwrap_or_default())
                .replace("{1}", GUI_VERSION)
        }
        (_, theirs) => gettext(
            "Runs {0}, this GUI {1}: the two can't talk. Restart it or upgrade so they match",
        )
        .replace("{0}", theirs.unwrap_or_default())
        .replace("{1}", GUI_VERSION),
    }
}

/// The hover tip for the CLI row's version chip. The CLI never talks to
/// the GUI; both ship in one package, so a different release means the
/// `tisvlay` on PATH comes from another install.
fn cli_tip(health: ServiceHealth, theirs: &str) -> String {
    match health {
        ServiceHealth::Offline => gettext("tisvlay not found on PATH"),
        ServiceHealth::Ok => gettext("Same release as this GUI"),
        _ => gettext("From a different install: {0}, this GUI {1}")
            .replace("{0}", theirs)
            .replace("{1}", GUI_VERSION),
    }
}

/// Probe the CLI's version by shelling out to `tisvlay --version`.
/// clap's default `--version` output is `tisvlay 0.1.0\n`; we take
/// the second whitespace-separated token. Returns `None` on any
/// failure (binary not on PATH, exit non-zero, unparsable output).
pub(crate) async fn probe_cli_version() -> Option<String> {
    let output = tokio::process::Command::new("tisvlay")
        .arg("--version")
        .output()
        .await
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let stdout = String::from_utf8(output.stdout).ok()?;
    stdout.split_whitespace().nth(1).map(str::to_string)
}

/// Build the COMPONENTS-table model for the About pane. Each row
/// gets a status circle on the left and a version chip on the right,
/// both colored by the row's health. Presence is liveliness, only:
/// each peer's `online` comes from its liveliness flag, the same
/// source as the sidebar footer, while the release check's `PeerInfo` fills
/// version/config *content* ("—" until the check lands; an unanswered check
/// never renders offline). GUI is hardcoded online with its
/// compile-time `CARGO_PKG_VERSION`; the CLI row reflects the
/// `--version` shell-out, compared against this GUI's release.
pub(crate) fn make_about_components(
    site: &str,
    daemon: (bool, Option<&PeerInfo>),
    session: (bool, Option<&PeerInfo>),
    tray: (bool, Option<&PeerInfo>),
    cli_version: Option<&str>,
) -> Vec<AboutComponentRow> {
    struct Cells {
        version: String,
        health: ServiceHealth,
        online: bool,
        chip: String,
        tip: String,
        config_path: String,
    }
    let peer_row = |(online, info): (bool, Option<&PeerInfo>)| {
        let health = service_health(online, info);
        let theirs = info.map(|info| info.version.as_str());
        Cells {
            version: match (online, theirs) {
                (true, Some(v)) => v.to_string(),
                (true, None) => "—".to_string(),
                (false, _) => String::new(),
            },
            health,
            online,
            chip: match (online, theirs) {
                (true, Some(v)) => format!("v{v}"),
                (true, None) => "—".to_string(),
                (false, _) => gettext("offline"),
            },
            tip: service_tip(health, theirs),
            config_path: info
                .map(|info| info.config_path.clone())
                .unwrap_or_default(),
        }
    };
    let parens = |identity: String| {
        if identity.is_empty() {
            String::new()
        } else {
            format!("({identity})")
        }
    };

    COMPONENT_CATALOGUE
        .iter()
        .map(|(name, friendly, description)| {
            // The wire identity shown in monospace parens: the peer's
            // liveliness key (presence on the zenoh bus), except the
            // GUI, whose identity is its real D-Bus activation name.
            let identity = match *name {
                "tisvlay-daemon" => tisvlay_protocol::keys::daemon_alive(site),
                "tisvlay-session" => tisvlay_protocol::keys::user_alive_session(site),
                "tisvlay-tray" => tisvlay_protocol::keys::user_alive_tray(site),
                "tisvlay-gui" => "org.tisvlay.Gui".to_string(),
                _ => String::new(),
            };
            let cells = match *name {
                "tisvlay-daemon" => peer_row(daemon),
                "tisvlay-session" => peer_row(session),
                "tisvlay-tray" => peer_row(tray),
                // GUI has no config file yet (passes `None` to dbus::register).
                "tisvlay-gui" => Cells {
                    version: GUI_VERSION.to_string(),
                    health: ServiceHealth::Ok,
                    online: true,
                    chip: format!("v{GUI_VERSION}"),
                    tip: gettext("This window's release"),
                    config_path: String::new(),
                },
                // CLI has no per-binary config of its own — its
                // settings live in the daemon/session configs.
                "tisvlay" => {
                    let health = cli_version.map_or(ServiceHealth::Offline, release_health);
                    let theirs = cli_version.unwrap_or_default();
                    Cells {
                        version: theirs.to_string(),
                        health,
                        online: cli_version.is_some(),
                        chip: match cli_version {
                            Some(v) => format!("v{v}"),
                            None => gettext("not found"),
                        },
                        tip: cli_tip(health, theirs),
                        config_path: String::new(),
                    }
                }
                _ => Cells {
                    version: String::new(),
                    health: ServiceHealth::Offline,
                    online: false,
                    chip: String::new(),
                    tip: String::new(),
                    config_path: String::new(),
                },
            };
            AboutComponentRow {
                name: SharedString::from(*name),
                friendly_name: SharedString::from(*friendly),
                bus_address: SharedString::from(parens(identity)),
                description: SharedString::from(*description),
                version: SharedString::from(cells.version),
                health: cells.health,
                online: cells.online,
                chip: SharedString::from(cells.chip),
                tip: SharedString::from(cells.tip),
                config_path: SharedString::from(cells.config_path),
            }
        })
        .collect()
}

/// Cached supported-vendor IDs (the daemon's `manager/vendors`
/// catalog), populated once at startup and read by the
/// diagnostic-blob builder. `RwLock` rather
/// than `OnceCell` because the value is written from the async
/// startup path while the Slint callback reads from the main thread;
/// `std::sync::RwLock` avoids dragging tokio's flavor across the
/// thread boundary.
pub(crate) type SupportedVendorsCache = Arc<std::sync::RwLock<Vec<String>>>;

/// Build the diagnostic blob's [`diagnostic::Inputs`] from live
/// in-process state (Slint models + per-process context) and render
/// it to JSON. Schema lives in [`diagnostic`]; rationale in
/// `docs/diagnostics.md`.
pub(crate) fn build_diagnostic_blob(
    app: &AppWindow,
    user_bus: bool,
    vendors: &SupportedVendorsCache,
) -> String {
    let components: Vec<diagnostic::ComponentSnap> = {
        let model = app.get_about_components();
        (0..model.row_count())
            .filter_map(|i| model.row_data(i))
            .map(|row| diagnostic::ComponentSnap {
                name: row.name.to_string(),
                version: row.version.to_string(),
                connected: row.online,
                has_config: !row.config_path.as_str().is_empty(),
            })
            .collect()
    };
    let tvs: Vec<diagnostic::TvSnap> = {
        let model = app.get_tvs();
        (0..model.row_count())
            .filter_map(|i| model.row_data(i))
            .map(|row| diagnostic::TvSnap {
                vendor: row.vendor.to_string(),
                connected: row.connected,
            })
            .collect()
    };
    let supported_vendors = vendors
        .read()
        .map(|guard| guard.clone())
        .unwrap_or_default();
    diagnostic::build_blob(diagnostic::Inputs {
        components: &components,
        tvs: &tvs,
        user_bus,
        supported_vendors: &supported_vendors,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Availability is liveliness, only: a live peer whose info probe
    /// failed renders an online row with placeholder content — a failed
    /// rpc must never read as offline.
    #[test]
    fn live_peer_with_failed_probe_renders_online_with_placeholder() {
        let rows = make_about_components("t", (true, None), (false, None), (true, None), None);
        let row = |name: &str| {
            rows.iter()
                .find(|row| row.name == name)
                .expect("row present")
                .clone()
        };
        let daemon = row("tisvlay-daemon");
        assert!(daemon.online);
        assert_eq!(daemon.version, "—");
        let session = row("tisvlay-session");
        assert!(!session.online);
        assert_eq!(session.version, "");
        let tray = row("tisvlay-tray");
        assert!(tray.online);
        assert_eq!(tray.version, "—");
    }

    /// A probe that lands fills content and keeps the liveliness flag.
    #[test]
    fn probe_content_fills_without_touching_presence() {
        let info = PeerInfo {
            version: "9.9.9".into(),
            config_path: "/tmp/x.toml".into(),
        };
        let rows =
            make_about_components("t", (true, Some(&info)), (false, None), (false, None), None);
        let daemon = rows
            .iter()
            .find(|row| row.name == "tisvlay-daemon")
            .expect("row present");
        assert!(daemon.online);
        assert_eq!(daemon.version, "9.9.9");
        assert_eq!(daemon.config_path, "/tmp/x.toml");
    }

    /// The same release with only the patch bumped.
    fn patch_bump() -> String {
        let mut parts: Vec<u64> = GUI_VERSION
            .split('.')
            .map(|part| part.parse().expect("GUI_VERSION is major.minor.patch"))
            .collect();
        parts[2] += 1;
        format!("{}.{}.{}", parts[0], parts[1], parts[2])
    }

    /// The next minor release, which this GUI can't talk to.
    fn minor_bump() -> String {
        let mut parts: Vec<u64> = GUI_VERSION
            .split('.')
            .map(|part| part.parse().expect("GUI_VERSION is major.minor.patch"))
            .collect();
        parts[1] += 1;
        format!("{}.{}.0", parts[0], parts[1])
    }

    fn info(version: &str) -> PeerInfo {
        PeerInfo {
            version: version.into(),
            config_path: String::new(),
        }
    }

    /// Health tiers follow the handshake's rule: the same release is
    /// ok, a patch skew is compatible, any other major.minor (newer or
    /// older) is incompatible, and an absent service is offline
    /// whatever it last reported.
    #[test]
    fn service_health_tiers() {
        assert_eq!(
            service_health(true, Some(&info(GUI_VERSION))),
            ServiceHealth::Ok
        );
        assert_eq!(
            service_health(true, Some(&info(&patch_bump()))),
            ServiceHealth::Skew
        );
        assert_eq!(
            service_health(true, Some(&info(&minor_bump()))),
            ServiceHealth::Incompatible
        );
        assert_eq!(
            service_health(true, Some(&info("0.0.1"))),
            ServiceHealth::Incompatible
        );
        assert_eq!(service_health(true, None), ServiceHealth::Ok);
        assert_eq!(
            service_health(false, Some(&info(GUI_VERSION))),
            ServiceHealth::Offline
        );
    }

    /// Rows carry the health, the chip label and a tip naming both
    /// releases when they differ.
    #[test]
    fn rows_render_health_chip_and_tip() {
        let minor = minor_bump();
        let rows = make_about_components(
            "t",
            (true, Some(&info(&minor))),
            (true, None),
            (false, None),
            Some(&patch_bump()),
        );
        let row = |name: &str| {
            rows.iter()
                .find(|row| row.name == name)
                .expect("row present")
                .clone()
        };
        let daemon = row("tisvlay-daemon");
        assert_eq!(daemon.health, ServiceHealth::Incompatible);
        assert_eq!(daemon.chip, format!("v{minor}"));
        assert!(daemon.tip.contains(minor.as_str()) && daemon.tip.contains(GUI_VERSION));
        let session = row("tisvlay-session");
        assert_eq!(session.health, ServiceHealth::Ok);
        assert_eq!(session.chip, "—");
        let tray = row("tisvlay-tray");
        assert_eq!(tray.health, ServiceHealth::Offline);
        assert_eq!(tray.chip, "offline");
        let cli = row("tisvlay");
        assert_eq!(cli.health, ServiceHealth::Skew);
        assert!(cli.tip.contains("different install"));
        let gui = row("tisvlay-gui");
        assert_eq!(gui.health, ServiceHealth::Ok);
    }

    /// A CLI missing from PATH is offline, labeled "not found".
    #[test]
    fn missing_cli_reads_not_found() {
        let rows = make_about_components("t", (false, None), (false, None), (false, None), None);
        let cli = rows
            .iter()
            .find(|row| row.name == "tisvlay")
            .expect("row present");
        assert_eq!(cli.health, ServiceHealth::Offline);
        assert!(!cli.online);
        assert_eq!(cli.chip, "not found");
    }
}
